package mrpapermoon.whisper.contacts.dbimport android.content.Contextimport androidx.room.Databaseimport androidx.room.Roomimport androidx.room.RoomDatabaseimport androidx.room.TypeConverters@Database(	entities = [ContactEntity::class],	version = 1,	exportSchema = false)@TypeConverters(RoomTypeConverters::class)abstract class ContactsDatabase : RoomDatabase() {	abstract fun contactDao(): ContactDao	companion object Factory {		@Volatile		private var instance: ContactsDatabase? = null		@Synchronized		fun getDatabase(context: Context): ContactsDatabase {			if (instance == null) {				instance = Room.databaseBuilder(					context.applicationContext,					ContactsDatabase::class.java,					"contacts_database"				).build()			}			return instance!!		}	}}